            break :blk ptr[0..self.len];

}), .capacity = self.cap, .allocator = self.allocator } };
            _ = &result;
            self.allocator = default_allocator;
            self.len = (if (comptime @typeInfo(SizeType) == .@"enum" and (@typeInfo(@TypeOf(0)) == .int or @typeInfo(@TypeOf(0)) == .comptime_int)) @as(SizeType, @enumFromInt(0)) else @as(SizeType, 0));
            self.cap = (if (comptime @typeInfo(SizeType) == .@"enum" and (@typeInfo(@TypeOf(0)) == .int or @typeInfo(@TypeOf(0)) == .comptime_int)) @as(SizeType, @enumFromInt(0)) else @as(SizeType, 0));
            return result;
    }

pub fn slice(self: *const StoreBytes) []u8 {
            if ((self.ptr != null)) {
                return (blk: {
                break :blk self.ptr.?[0..self.len];

});
            }
            return "";
    }

pub fn allocatedSlice(self: *const StoreBytes) []u8 {
            if ((self.ptr != null)) {
                return (blk: {
                break :blk self.ptr.?[0..self.cap];

});
            }
            return "";
    }

pub fn deinit(self: *StoreBytes) void {
            _ = default_allocator.free(self.stored_name.slice());
            if ((self.ptr != null)) {
                _ = self.allocator.free((blk: {
                break :blk self.ptr.?[0..self.cap];

}));
            }
            self.ptr = null;
            self.len = (if (comptime @typeInfo(SizeType) == .@"enum" and (@typeInfo(@TypeOf(0)) == .int or @typeInfo(@TypeOf(0)) == .comptime_int)) @as(SizeType, @enumFromInt(0)) else @as(SizeType, 0));
            self.cap = (if (comptime @typeInfo(SizeType) == .@"enum" and (@typeInfo(@TypeOf(0)) == .int or @typeInfo(@TypeOf(0)) == .comptime_int)) @as(SizeType, @enumFromInt(0)) else @as(SizeType, 0));
    }

pub fn asArrayList(self: StoreBytes) ArrayListUnmanaged(u8) {
            return self.asArrayListLeak();
    }

pub fn asArrayListLeak(self: StoreBytes) ArrayListUnmanaged(u8) {
            return .{ .items = (if ((self.ptr != null)) (blk: {
            break :blk self.ptr.?[0..self.len];

}) else (&.{})), .capacity = self.cap };
    }
};

pub const Store = struct {
    data: Data,
    mime_type: MimeType = .none,
    ref_count: AtomicValue(u32) = AtomicValue(u32).init(1),
    is_all_ascii: ?bool = null,
    allocator: Allocator,
    
pub fn _create(allocator: std.mem.Allocator) !*@This() { const self_ptr = try allocator.create(@This()); self_ptr.* = undefined; self_ptr.mime_type = .none; self_ptr.ref_count = AtomicValue(u32).init(1); self_ptr.is_all_ascii = null; return self_ptr; }

pub fn memoryCost(self: *const Store) usize {
            return (if (self.hasOneRef()) (@sizeOf(Store) + (switch (self.data) {
.bytes => self.data.bytes.len,
.file => 0,
.s3 => |s3| s3.estimatedSize(),
})) else 0);
    }

pub fn getPath(self: *const Store) ?[]const u8 {
            return (switch (self.data) {
.bytes => |bytes| (if ((bytes.stored_name.len > 0)) bytes.stored_name.slice() else null),
.file => |file| (if ((file.pathlike == .path)) file.pathlike.path.slice() else null),
.s3 => |s3| s3.pathlike.slice(),
});
    }

pub fn size(self: *const Store) SizeType {
            return (switch (self.data) {
.bytes => self.data.bytes.len,
.s3, .file => Blob.max_size,
});
    }

pub fn ref(self: *Store) void {
            var old = self.ref_count.fetchAdd(1, .monotonic);
            _ = &old;
            _ = assert((old > 0));
    }

pub fn hasOneRef(self: *const Store) bool {
            return (self.ref_count.load(.monotonic) == 1);
    }

pub fn toAnyBlob(self: *Store) ?Blob.Any {
            if (self.hasOneRef()) {
                if ((self.data == .bytes)) {
                    return .{ .InternalBlob = self.data.bytes.toInternalBlob() };
                }
            }
            return null;
    }

pub fn external(ptr: ?*anyopaque, _: ?*anyopaque, _: usize) callconv(.c) void {
            if ((ptr == null)) {
                return;
            }
            var this_store: *Store = bun.cast(*Store, ptr.?);
            _ = &this_store;
            _ = this_store.deref();
    }

pub fn initS3WithReferencedCredentials(pathlike: node.PathLike, mime_type: ?MimeType, credentials: *S3Credentials, allocator: Allocator) !*Store {
            var path = pathlike;
            _ = &path;
            _ = path.toThreadSafe();
            return bun.new(Store, .{ .data = .{ .s3 = StoreS3.initWithReferencedCredentials(path, ((mime_type) orelse (brk: {
            var sliced = path.slice();
            _ = &sliced;
            if ((sliced.len > 0)) {
                var extname_raw = std.fs.path.extension(sliced);
                _ = &extname_raw;
                var extname = std.mem.trim(u8, extname_raw, ".");
                _ = &extname;
                if (MimeType.byExtensionNoDefault(extname)) |mime| {
                    _ = &mime;
                    break :brk mime;
                }
            }
            break :brk null;
})), credentials) }, .allocator = allocator, .ref_count = AtomicValue(u32).init(1) });
    }

pub fn initS3(pathlike: node.PathLike, mime_type: ?MimeType, credentials: S3Credentials, allocator: Allocator) !*Store {
            var path = pathlike;
            _ = &path;
            _ = path.toThreadSafe();
            return bun.new(Store, .{ .data = .{ .s3 = StoreS3.init(path, ((mime_type) orelse (brk: {
            var sliced = path.slice();
            _ = &sliced;
            if ((sliced.len > 0)) {
                var extname_raw = std.fs.path.extension(sliced);
                _ = &extname_raw;
                var extname = std.mem.trim(u8, extname_raw, ".");
                _ = &extname;
                if (MimeType.byExtensionNoDefault(extname)) |mime| {
                    _ = &mime;
                    break :brk mime;
                }
            }
            break :brk null;
})), credentials) }, .allocator = allocator, .ref_count = AtomicValue(u32).init(1) });
    }

pub fn initFile(pathlike: Node.PathOrFileDescriptor, mime_type: ?MimeType, allocator: Allocator) !*Store {
            return bun.new(Store, .{ .data = .{ .file = StoreFile.init(pathlike, ((mime_type) orelse (brk: {
            if ((pathlike == .path)) {
                var sliced = pathlike.path.slice();
                _ = &sliced;
                if ((sliced.len > 0)) {
                    var extname_raw = std.fs.path.extension(sliced);
                    _ = &extname_raw;
                    var extname = std.mem.trim(u8, extname_raw, ".");
                    _ = &extname;
                    if (MimeType.byExtensionNoDefault(extname)) |mime| {
                        _ = &mime;
                        break :brk mime;
                    }
                }
            }
            break :brk null;
}))) }, .allocator = allocator, .ref_count = AtomicValue(u32).init(1) });
    }

pub fn init(bytes: []u8, allocator: Allocator) *Store {
            return bun.new(Store, .{ .data = .{ .bytes = StoreBytes.init(bytes, allocator) }, .allocator = allocator, .ref_count = AtomicValue(u32).init(1) });
    }

pub fn sharedView(self: *const Store) []u8 {
            if ((self.data == .bytes)) {
                return self.data.bytes.slice();
            }
            return "";
    }

pub fn deref(self: *Store) void {
            var old = self.ref_count.fetchSub(1, .monotonic);
            _ = &old;
            _ = assert((old >= 1));
            if ((old == 1)) {
                _ = self.deinit();
            }
    }

pub fn deinit(self: *Store) void {
            var allocator = self.allocator;
            _ = &allocator;
            switch (self.data) {
.bytes => |*bytes| {
_ = bytes.deinit();
},
.file => |file| {
if ((file.pathlike == .path)) {
                switch (file.pathlike.path) {
.string => {
_ = allocator.free((blk: {
                break :blk @constCast(file.pathlike.path.slice());

}));
},
else => {
_ = file.pathlike.path.deinit();
},
}
            }
},
.s3 => |*s3| {
_ = s3.deinit(allocator);
},
}
            _ = destroy(self);
    }

pub fn serialize(self: *Store, comptime Writer: type, writer: Writer) !void {
            switch (self.data) {
.file => |file| {
switch (file.pathlike) {
.fd => |fd| {
_ = try writer.writeInt(u8, 0, .little);
            _ = try writer.writeStruct(fd);
},
.path => |path| {
_ = try writer.writeInt(u8, 1, .little);
            var path_slice = path.slice();
            _ = &path_slice;
            _ = try writer.writeInt(u32, @as(u32, @truncate(path_slice.len)), .little);
            _ = try writer.writeAll(path_slice);
},
}
},
.s3 => |s3| {
_ = try writer.writeInt(u8, 1, .little);
            var path_slice = s3.pathlike.slice();
            _ = &path_slice;
            _ = try writer.writeInt(u32, @as(u32, @truncate(path_slice.len)), .little);
            _ = try writer.writeAll(path_slice);
},
.bytes => |bytes| {
var slice = bytes.slice();
            _ = &slice;
            _ = try writer.writeInt(u32, @truncate(slice.len), .little);
            _ = try writer.writeAll(slice);
            _ = try writer.writeInt(u32, @truncate(bytes.stored_name.slice().len), .little);
            _ = try writer.writeAll(bytes.stored_name.slice());
},
}
    }

pub fn fromArrayList(list: ArrayListUnmanaged(u8), allocator: Allocator) !*Store {
            return Store.init(list.items, allocator);
    }
    pub const new = bun.TrivialNew(@This());
